package com.fakrudeenmart.servlet;
import com.fakrudeenmart.service.AdminService; import com.fakrudeenmart.service.CategoryService;
import javax.servlet.ServletException; import javax.servlet.http.*; import java.io.IOException; import java.math.BigDecimal;
public class AdminProductEditServlet extends HttpServlet { private AdminService service; private CategoryService categories; public void init(){service=new AdminService();categories=new CategoryService();} protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{long id=AdminServletSupport.id(req.getParameter("id"),"Product was not found.");req.setAttribute("product",service.getProduct(AdminServletSupport.adminId(req),id));req.setAttribute("categories",categories.getAllCategories());req.setAttribute("formAction",req.getContextPath()+"/admin/products/edit?id="+id);req.getRequestDispatcher("/WEB-INF/views/admin/product-edit.jsp").forward(req,resp);} protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{long id=AdminServletSupport.id(req.getParameter("id"),"Product was not found.");int stock=Integer.parseInt(req.getParameter("stockQuantity"));service.updateProduct(AdminServletSupport.adminId(req),id,AdminServletSupport.id(req.getParameter("categoryId"),"Category was not found."),req.getParameter("name"),req.getParameter("description"),new BigDecimal(req.getParameter("price")),stock,req.getParameter("imageUrl"),AdminServletSupport.productStatus(req.getParameter("status")));resp.sendRedirect(req.getContextPath()+"/admin/products");}catch(Exception e){req.setAttribute("error",AdminServletSupport.message(e,"Unable to update product."));req.setAttribute("categories",categories.getAllCategories());req.setAttribute("formAction",req.getContextPath()+"/admin/products/edit?id="+req.getParameter("id"));req.getRequestDispatcher("/WEB-INF/views/admin/product-edit.jsp").forward(req,resp);}}}
